var species = get('specieSelection') || [];
var helper = API.cache('helper');
if(!helper) {
    helper = new ChemEquilibrium.Helper();
    API.cache('helper', helper);
}

localStorage.setItem('chem-equilibrium-species', JSON.stringify(species));
helper.resetSpecies();
for(var i=0; i<species.length; i++) {
    var specie = species[i];
    console.log(specie)
    helper.addSpecie(String(specie.label), Number(specie.qty));
}

(API.getData('equations') || []).forEach(e => {
    if(DataObject.resurrect(e.disabled)) {
        console.log('disable equation', e.chemEq.formed);
        helper.disableEquation(String(e.chemEq.formed));
    } else {
        helper.enableEquation(String(e.chemEq.formed));
    }
});

var chemEq = helper.getEquations({filtered: true, includeDisabled: true});
console.log(chemEq)
var normalizedEq = helper.getEquations({filtered: true, normalized: true, includeDisabled: true});
var equations = chemEq.map((eq, idx) => {
    return {
        chemEq: eq,
        normalizedEq: normalizedEq[idx],
        disabled: eq.disabled ? true : false
    }
});
API.createData('equations', equations).then(function() {
    console.log('create schema')
        API.createData('schema', getSchema(species));
});

function getSchema(species) {
    var components = helper.getComponents({filtered: true});
    console.log('components', components);
    var config = API.getData('config');
    if(config && config.fixed) {
        var defaultFixed = String(config.fixed);
    } else {
        defaultFixed = components[0]
    }
    var schema = {
        type: 'object',
        properties: {
            varying: {
                type: 'string',
                enum: components,
                default: defaultFixed,
                label: 'Varying component'
            },
            isFixed: {
                label: 'Fixed at equilibrium',
                type: 'boolean',
                default: false
            },
            from: {
                type: 'number',
                default: 1e-14
            },
            to: {
                type: 'number',
                default: 1
            },
            log: {
                type: 'boolean',
                default: false
            },
            tolerance: {
                type: 'number',
                default: 1e-15
            },
            solidTolerance: {
                type: 'number',
                default: 1e-8
            },
            maxIterations: {
                type: 'number',
                default: 100
            },
            chunks: {
                type: 'number',
                default: 200,
                label: 'Nb points in graph'
            }
        }
    }
    return schema;
}

