var chart = Chart.getChart(sol.x, sol.solutions, {
    xLabel: config.isFixed ? ('Quantity ' + (config.log ? '-log10 of ' : 'of ') + config.varying + 'at equilibrium ' + config.log ? '' : '[mol]') : ('Total quantity of ' + config.varying),
    yLabel: 'Amount of other species at equilibrium [mol]'
});


API.createData('errorCount', sol.errorCount);
API.createData('chartSpecies', sol.species);
API.createData('chart', chart);
API.createData('model', helper.getModel());

localStorage.debug = '*';

require([
    'https://www.lactame.com/github/cheminfo-js/visualizer-helper/d32e267148e104f56ebfd1d9e4855ddd20f39a6b/util/trackArray.js',
    'https://www.lactame.com/github/cheminfo-js/visualizer-helper/d32e267148e104f56ebfd1d9e4855ddd20f39a6b/util/track.js',
    'ChemEquilibrium'], function (trackArray, track, ChemEquilibrium) {
    trackArray('chem-equilibrium-species', [], function(entry) {return entry.specie}, {varName: 'specieSelection'}) ;
    track('chem-equilibrium-config', {}, {varName: 'config'});


    var helper = new ChemEquilibrium.Helper();

    if(typeof IframeBridge !== "undefined") {
        IframeBridge.onMessage(function(data) {
            if(!data.message) return;
            if(data.message.localStorageId) {
                var s = JSON.parse(localStorage.getItem(data.message.localStorageId));        
            }
            API.onAction('speciesLoaded', function () {
                if(s) {
                    API.doAction('selectSpecies', function (row) {return s.find(s => String(s.label) === String(row.label))});    
                }
            });

            API.createData('allSpecies', helper.getSpecies({type: data.message.eqType}).map(speciesMap));
        });
        IframeBridge.ready();    
    } else {
        API.createData('allSpecies', helper.getSpecies().map(speciesMap));
    }

});

function speciesMap(label) {
    return {
        label: label,
        qty: 1
    }
}

